<script setup>
import{ref,onMounted}from'vue';import{api}from'../services/api.js';import{can}from'../stores/auth.js';import UiState from'../components/UiState.vue'
const form=ref({}),loading=ref(true),error=ref(''),success=ref('');async function load(){try{form.value=await api.get('/company');if(typeof form.value.modules==='string')form.value.modules=JSON.parse(form.value.modules)}catch(e){error.value=e.message}finally{loading.value=false}}async function save(){error.value='';success.value='';try{await api.put('/company',form.value);success.value='Configuració desada correctament.'}catch(e){error.value=e.message}}onMounted(load)
</script>
<template><UiState :loading="loading" :error="error"><form class="card settings form-grid" @submit.prevent="save"><label>Nom comercial<input v-model="form.trade_name" required></label><label>Nom fiscal<input v-model="form.legal_name"></label><label>NIF/CIF<input v-model="form.tax_id"></label><label>Telèfon<input v-model="form.phone" type="tel"></label><label class="full">Adreça<input v-model="form.address"></label><label>Correu electrònic<input v-model="form.email" type="email"></label><label>URL del logotip<input v-model="form.logo_url" type="url"></label><label>Color corporatiu<input v-model="form.primary_color" type="color"></label><label>Zona horària<input v-model="form.timezone"></label><label>Idioma<select v-model="form.language"><option value="ca">Català</option><option value="es">Castellà</option></select></label><label>Format de data<select v-model="form.date_format"><option>DD/MM/YYYY</option><option>YYYY-MM-DD</option></select></label><section class="full module-box"><h2>Mòduls</h2><p class="muted">No hi ha mòduls de negoci disponibles en aquesta fase.</p></section><div v-if="success" class="alert success full" role="status">{{success}}</div><button v-if="can('company.manage')" class="button primary">Desar canvis</button></form></UiState></template>
